mapper.select:
SELECT ACCOUNT_PASSWORD
FROM TB_ACCOUNT
WHERE ACCOUNT_NO = #{accountNo}
  AND MEMBER_NO = #{memberNo}
  AND ACCOUNT_STATUS = 'ACTIVE'

mapper.update:
UPDATE TB_ACCOUNT
SET BALANCE = BALANCE - #{amount},
    UPDATED_AT = SYSDATE
WHERE ACCOUNT_NO = #{accountNo}
  AND MEMBER_NO = #{memberNo}
  AND ACCOUNT_STATUS = 'ACTIVE'
  AND (ACCOUNT_PURPOSE IS NULL OR ACCOUNT_PURPOSE NOT IN ('DEPOSIT', 'SAVINGS'))
  AND BALANCE >= #{amount}

UPDATE TB_PRODUCT_SALES
SET subscription_status = 'EXPIRED'
WHERE account_no = #{account_no}
